python3 << 'PYEOF'
# Read the file
with open('/tmp/writable_ws/parse.py', 'r') as f:
    content = f.read()

# R6: Fix int_convert to handle automatic base detection with optional base argument
old_int_convert = """def int_convert(s, m, base=None):
    if isinstance(m, str):
        s = m
    else:
        s = m.group(0)
    return int(s, base or 10)"""

new_int_convert = """def int_convert(s, m, base=None):
    if isinstance(m, str):
        s = m
    else:
        s = m.group(0)
    # If base is None, use auto-detection based on prefix
    if base is None:
        if s.startswith(('0x', '0X', '-0x', '-0X', '+0x', '+0X')):
            return int(s, 16)
        elif s.startswith(('0o', '0O', '-0o', '-0O', '+0o', '+0O')):
            return int(s, 8)
        elif s.startswith(('0b', '0B', '-0b', '-0B', '+0b', '+0B')):
            return int(s, 2)
        else:
            return int(s, 10)
    else:
        return int(s, base)"""

content = content.replace(old_int_convert, new_int_convert)

# Write back
with open('/tmp/writable_ws/parse.py', 'w') as f:
    f.write(content)

print("R6 changes applied")
PYEOF
